  "indicator_readings": [
    {
      "indicator": "Preço (fechamento)",
      "reading": "≈ R$13,10 (fechamento 2025-01-02)",
      "interpretation": "Fechamento abaixo da MM20 e próximo à metade inferior das Bandas de Bollinger; perto do suporte recente."
    },
    {
      "indicator": "MM20",
      "reading": "≈ R$13,4",
      "interpretation": "Inclinação ligeiramente descendente; cruzou abaixo da MM50, sinal de fraqueza de curto prazo."
    },
    {
      "indicator": "MM50",
      "reading": "≈ R$13,9",
      "interpretation": "Nivel de resistência/congestionamento no curto/médio prazo; inclinada lateral a levemente descendente."
    },
    {
      "indicator": "MM200",
      "reading": "≈ R$12,4",
      "interpretation": "Tendência de longo prazo ainda positiva (MM200 ascendente); preço permanece acima dela."
    },
    {
      "indicator": "EMA9",
      "reading": "≈ R$13,3",
      "interpretation": "Rápida e abaixo do preço/EMA21 recentemente; reflete reversão de curto prazo para baixa."
    },
    {
      "indicator": "EMA21",
      "reading": "≈ R$13,4",
      "interpretation": "Convergindo com EMA9; confirma perda de impulso de curtíssimo prazo."
    },
    {
      "indicator": "MACD (12,26,9)",
      "reading": "MACD < sinal; histograma levemente negativo",
      "interpretation": "Momentum de curto/médio prazo fraco; cruzamento inferior recente indica pressão vendedora."
    },
    {
      "indicator": "Bandas de Bollinger (20,2σ)",
      "reading": "Bandas em estreitamento; preço na metade inferior",
      "interpretation": "Baixa volatilidade atual; estreitamento precede possibilidade de movimento mais forte se houver rompimento."
    },
    {
      "indicator": "RSI14",
      "reading": "≈ 45",
      "interpretation": "Neutro a levemente baixista; sem condição de sobrecompra/sobrevenda."
    },
    {
      "indicator": "Volume",
      "reading": "Volumes recentes baixos vs. picos anteriores",
      "interpretation": "Movimentos sem confirmação por volume; baixa convicção em rompimentos até aumento de participação."
    }
  ]
}
